glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
  uniform sampler2D normalMap;
#endif
uniform FragConstants {
    float v_offset;
  };
  vec2 get_fixuv_by_uv(vec2 uv) {
      if (uv.x > 1.0) {
          uv.x -= 1.0;
      }
      if (uv.x < 0.0) {
          uv.x += 1.0;
      }
      if (uv.y > 1.0) {
          uv.y -= 1.0;
      }
      if (uv.y < 0.0) {
          uv.y += 1.0;
      }
      return uv;
  }
  vec3 get_normal() {
      vec2 uv = v_uv0 + vec2(v_offset,1);
      uv = get_fixuv_by_uv(uv);
      return normalize(texture2D(normalMap, uv).xyz * 2.0 - 1.3);
  }
  vec2 get_uv_by_refract(vec3 refractVec) {
      vec2 uv = v_uv0 + vec2(refractVec) * 0.5;
      return uv;
  }
void main () {
    vec3 eyePos = vec3(0.5, 0.5, 10);
    vec3 inVec = normalize(vec3(v_uv0, 0.0) - eyePos);
    vec3 normal = get_normal();
    vec3 refractVec = refract(inVec, normal, 0.8);
    vec2 v_texCoordA = get_uv_by_refract(refractVec);
    gl_FragColor = texture2D(texture, v_texCoordA);
}

